mapper.select:
SELECT sc.id, sc.student_id, sc.course_id, sc.score, sc.term, sc.exam_time, s.name AS student_name, s.student_no AS student_no, c.course_name AS course_name, c.course_code AS course_code, c.credit AS credit FROM scores sc JOIN students s ON s.id = sc.student_id JOIN courses c ON c.id = sc.course_id WHERE s.class_id = #{classId}
AND sc.term = #{term}
ORDER BY sc.student_id ASC, sc.course_id ASC, sc.exam_time ASC
